{
  "name": "opencode-axonhub-connect",
  "version": "0.3.2",
  "description": "OpenCode V2 plugin that connects to AxonHub through /connect and routes models by protocol",
  "type": "module",
  "main": "./src/index.ts",
  "types": "./src/index.ts",
  "exports": {
    ".": "./src/index.ts"
  },
  "files": [
    "src",
    "server.ts",
    "README.md",
    "README.en.md",
    "LICENSE"
  ],
  "scripts": {
    "check": "tsc --noEmit"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "axonhub",
    "llm",
    "gateway",
    "responses-api"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/mlang233/opencode-axonhub-connect.git"
  },
  "homepage": "https://github.com/mlang233/opencode-axonhub-connect#readme",
  "bugs": {
    "url": "https://github.com/mlang233/opencode-axonhub-connect/issues"
  },
  "devDependencies": {
    "@opencode/plugin": "^2.0.32",
    "@types/node": "^24.0.0",
    "typescript": "^5.9.3"
  },
  "peerDependencies": {
    "@opencode/plugin": "*"
  }
}
